未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。第三方字体保留其许可证。 */
/* src/tokens.css */
@font-face {font-family:'Noto Sans SC';src:url('https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/notosanssc/notosanssc.woff2') format('woff2');font-weight:100 900;font-style:normal;font-display:swap;}
:root {
 --br-paper:#f8f8f4; --br-white:#ffffff; --br-ink:#171717; --br-blue:#1600ff;
 --br-font:'Noto Sans SC','Microsoft YaHei',sans-serif;
 --br-offset:4px 4px 0 var(--br-blue); --br-focus:2px solid var(--br-blue);
 --st-theme-mobile-reading-width:100%; --st-theme-mobile-reading-padding:0.25em;
 --topBarBlockSize:4.25rem;
}

/* src/kernel/scrollbars.css */
/* 仅隐藏浏览器滚动条外观，保留全部滚动交互。 */
::-webkit-scrollbar { display:none !important; }
* { scrollbar-width:none !important; -ms-overflow-style:none !important; }

/* src/chat-layout.css */
body {
  color:var(--br-ink);
  background-color:var(--br-paper);
  font-family:var(--br-font);
  text-shadow:none;
}

#chat {
  background-color:var(--br-paper);
  border-color:var(--br-ink);
  padding:1em 1.25em;
}

#chat .mes[is_system="false"] {
  flex-direction:column;
  align-items:stretch;
  gap:.45em;
  padding:1em 0 1.75em;
  border-bottom:2px solid var(--br-ink);
  background-color:var(--br-paper);
}

#chat .mes[is_system="false"] > .mesAvatarWrapper {
  flex:0 0 auto;
  align-self:flex-start;
  padding:0;
  margin:0;
}

#chat .mes[is_user="true"][is_system="false"] > .mesAvatarWrapper {
  align-self:flex-end;
}

#chat .mes[is_system="false"] > .mes_block {
  inline-size:100%;
  min-inline-size:0;
  padding:0;
  overflow:visible;
}

#chat .mes[is_system="false"] .avatar {
  inline-size:5.4em;
  block-size:5.4em;
  padding:.2em;
  border:3px solid var(--br-ink);
  border-radius:0;
  background-color:var(--br-white);
  box-shadow:var(--br-offset);
  transform:rotate(-2deg);
}

#chat .mes[is_system="false"] .avatar img {
  inline-size:100%;
  block-size:100%;
  object-fit:cover;
  border-radius:0;
}

#chat .mes[is_user="true"][is_system="false"] .avatar {
  inline-size:4.1em;
  block-size:4.1em;
  transform:rotate(2deg);
}

#chat .ch_name {
  gap:.5em;
  align-items:baseline;
  flex-wrap:wrap;
  color:var(--br-ink);
  text-shadow:none;
  margin-bottom:.65em;
}

#chat .name_text {
  font-family:var(--br-font);
  font-weight:900;
  font-size:1.9em;
  letter-spacing:-.06em;
  color:var(--br-ink);
}

#chat .timestamp, #chat .mesIDDisplay, #chat .mes_timer, #chat .tokenCounterDisplay {
  font-size:.72em;
  color:var(--br-ink);
  opacity:1;
  text-shadow:none;
}

#chat .mes[is_user="true"] .mes_text {
  border-bottom:5px solid var(--br-blue);
  background-color:var(--br-white);
  padding:.45em .6em;
  inline-size:fit-content;
  max-inline-size:100%;
  margin-inline-start:auto;
  font-weight:700;
}

#chat .mes[is_system="true"] {
  background-color:var(--br-ink);
  color:var(--br-white);
  border:2px solid var(--br-blue);
  padding:1em;
}

#chat .mes.selected {
  background-color:var(--br-white);
  outline:var(--br-focus);
}

@media (max-width: 700px) {
#chat .mes[is_system="false"] {
  flex-direction:column;
  align-items:stretch;
  padding-block:1em;
}
}

@media (max-width: 700px) {
#chat .mes[is_system="false"] > .mesAvatarWrapper {
  align-self:center;
  margin-inline:auto;
}
}

@media (max-width: 700px) {
#chat .mes[is_system="false"] > .mes_block {
  inline-size:100%;
  min-inline-size:0;
}
}

@media (max-width: 700px) {
#chat .mes[is_system="false"] > .mes_block > .mes_text {
  inline-size:min(100%, var(--st-theme-mobile-reading-width));
  max-inline-size:100%;
  margin-inline:auto !important;
  padding-inline:var(--st-theme-mobile-reading-padding) !important;
  box-sizing:border-box;
}
}

/* src/full-text.css */
#chat .mes_text {
  font-family:var(--br-font);
  font-size:1em;
  font-weight:500;
  line-height:1.95;
  color:var(--br-ink);
  text-shadow:none;
  overflow-wrap:anywhere;
}

#chat .mes_text p {
  margin-block:0 .9em;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text:not(:has(.edit_textarea)) > p:first-child:not(:has(code, img))::first-letter {
  color:var(--br-white);
  background-color:var(--br-blue);
  font-weight:900;
  font-size:1.45em;
  padding:.02em .1em;
}

#chat .mes_text q, #chat .mes_text blockquote {
  background-color:var(--br-ink);
  color:var(--br-white);
  border-color:var(--br-blue);
  box-decoration-break:clone;
  -webkit-box-decoration-break:clone;
  padding:.1em .35em;
  text-shadow:none;
}

#chat .mes_text blockquote {
  border-inline-start:5px solid var(--br-blue);
  margin-inline:0;
  padding:.8em 1em;
}

#chat .mes_text strong {
  font-weight:900;
  color:var(--br-blue);
}

#chat .mes_text em {
  font-style:normal;
  color:var(--br-blue);
  text-decoration:underline;
}

#chat .mes_text q :is(strong,em), #chat .mes_text blockquote :is(strong,em) {
  color:var(--br-white);
}

#chat .mes_text :is(h1,h2,h3,h4) {
  font-family:var(--br-font);
  font-weight:900;
  color:var(--br-ink);
  border-bottom:3px solid var(--br-blue);
}

#chat .mes_text a {
  color:var(--br-blue);
  text-decoration:underline;
}

#chat .mes_text table {
  display:block;
  overflow-x:auto;
  max-inline-size:100%;
  border-color:var(--br-ink);
}

#chat .mes_text :is(td,th) {
  border:1px solid var(--br-ink);
  padding:.45em;
  background-color:var(--br-white);
  color:var(--br-ink);
}

#chat .mes_text :is(img,video) {
  max-inline-size:100%;
  height:auto;
}

#chat .mes_text hr {
  border:0;
  border-top:3px solid var(--br-ink);
}

